      "legacy_html": "\r\n\r\n<hr>\r\n\r\n<p><b>Konečná tabulka- Sezóna 2006/2007, III.třída<br>\r\n\r\n</b><br>\r\n </p>\r\n<div>\r\n  \r\n  <table>\r\n    <tr>\r\n      <td>\r\n        <p><b>1.</b></p>\r\n      </td>\r\n      <td>\r\n        <p><b>Sobíňov</b></p>\r\n      </td>\r\n      <td>\r\n        <p><b>26</b></p></td>\r\n      <td>\r\n        <p><b>20</b></p></td>\r\n      <td>\r\n        <p><b>2</b></p></td>\r\n      <td>\r\n        <p><b>4</b></p></td>\r\n      <td>\r\n        <p><b>86:26</b></p></td>\r\n      <td>\r\n        <p><b>62</b></p></td>\r\n      <td>\r\n        <p><b>+23</b></p></td>\r\n    </tr>\r\n    <tr>\r\n      <td>\r\n        <p>2.</p>\r\n      </td>\r\n      <td>\r\n        <p>Mírovka</p></td>\r\n      <td>\r\n        <p>26</p></td>\r\n      <td>\r\n        <p>19</p></td>\r\n      <td>\r\n        <p>2</p></td>\r\n      <td>\r\n        <p>5</p></td>\r\n      <td>\r\n        <p>77:25</p></td>\r\n      <td>\r\n        <p>59</p></td>\r\n      <td>\r\n        <p>+20</p></td>\r\n    </tr>\r\n    <tr>\r\n      <td>\r\n        <p>3.</p>\r\n      </td>\r\n      <td>\r\n        <p>Jeřišno</p></td>\r\n      <td>\r\n        <p>26</p></td>\r\n      <td>\r\n        <p>14</p></td>\r\n      <td>\r\n        <p>4</p></td>\r\n      <td>\r\n        <p>8</p></td>\r\n      <td>\r\n        <p>76:44</p></td>\r\n      <td>\r\n        <p>46</p></td>\r\n      <td>\r\n        <p>+7</p></td>\r\n    </tr>\r\n    <tr>\r\n      <td>\r\n        <p>4.</p>\r\n      </td>\r\n      <td>\r\n        <p>Rozsochatec</p></td>\r\n      <td>\r\n        <p>26</p></td>\r\n      <td>\r\n        <p>12</p></td>\r\n      <td>\r\n        <p>7</p></td>\r\n      <td>\r\n        <p>7</p></td>\r\n      <td>\r\n        <p>53:49</p></td>\r\n      <td>\r\n        <p>43</p></td>\r\n      <td>\r\n        <p>+4</p></td>\r\n    </tr>\r\n    <tr>\r\n      <td>\r\n        <p>5.</p>\r\n      </td>\r\n      <td>\r\n        <p>Maleč</p></td>\r\n      <td>\r\n        <p>26</p></td>\r\n      <td>\r\n     