      "legacy_html": "\r\n\r\n<hr>\r\n\r\n<p><b>Sezóna 2004/2005, IV.třída</b> \r\n\r\n</p>\r\n\r\n  <table>\r\n    <tr>\r\n      <td colspan=\"12\">\r\n        <p><b>Tabulka po skončení sezóny</b></p>\r\n      </td>\r\n    </tr>\r\n    <tr>\r\n      <td colspan=\"12\"> </td>\r\n    </tr>\r\n    <tr>\r\n      <td>#</td>\r\n      <td>  Tým</td>\r\n      <td>Z</td>\r\n      <td>V</td>\r\n      <td>R</td>\r\n      <td>P</td>\r\n      <td> </td>\r\n      <td>\r\n        <table>\r\n          <tbody>\r\n            <tr>\r\n              <td>\r\n\t\t\t\tVG</td>\r\n              <td>\r\n\t\t\t\t:</td>\r\n              <td>\r\n\t\t\t\tOG</td>\r\n            </tr>\r\n          </tbody>\r\n        </table>\r\n      </td>\r\n      <td> </td>\r\n      <td>+/-</td>\r\n      <td> </td>\r\n      <td>B</td>\r\n    </tr>\r\n    <tr>\r\n      <td>1. </td>\r\n      <td> Sokol Maleč</td>\r\n      <td>22</td>\r\n      <td>21</td>\r\n      <td>1</td>\r\n      <td>0</td>\r\n      <td> </td>\r\n      <td>\r\n        <table>\r\n          <tbody>\r\n            <tr>\r\n              <td>\r\n\t\t\t\t117</td>\r\n              <td>\r\n\t\t\t\t:</td>\r\n              <td>\r\n\t\t\t\t21</td>\r\n            </tr>\r\n          </tbody>\r\n        </table>\r\n      </td>\r\n      <td> </td>\r\n      <td>13</td>\r\n      <td> </td>\r\n      <td><b>64</b></td>\r\n    </tr>\r\n    <tr>\r\n      <td>2. </td>\r\n      <td> Velká Losenice</td>\r\n      <td>22</td>\r\n      <td>16</td>\r\n      <td>0</td>\r\n      <td>6</td>\r\n      <td> </td>\r\n      <td>\r\n        <table>\r\n          <tbody>\r\n            <tr>\r\n              <td>\r\n\t\t\t\t74</td>\r\n              <td>\r\n\t\t\t\t:</td>\r\n              <td>\r\n\t\t\t\t36</td>\r\n            </tr>\r\n          </tbody>\r\n        </table>\r\n      </td>\r\n      <td> </td>\r\n      <td>6</td>\r\n      <td> </td>\r\n      <td><b>48</b></td>\r\n    </tr>\r\n    <tr>\r\n      <td><b>3. </b></td>\r\n      <td><b> Sokol Sobíňov</b></td>\r\n      <td><b